<template><view class="page"><view class="head"><text class="eyebrow">个人中心</text><text class="title">我的兑换</text></view><view v-if="orders.length" class="list"><view v-for="item in orders" :key="item._id||item.id" class="card order"><view class="order-icon">▣</view><view class="order-main"><text class="name">{{item.productName||item.name}}</text><text class="muted">{{item.createdAt}}</text><text class="points">-{{item.points}} 积分 · {{item.status}}</text></view></view></view><view v-else class="empty card">暂无兑换商品</view></view></template>
<script>import {callCloud} from '../../common/cloud.js';export default{data(){return{orders:[]}},async onShow(){const userId=uni.getStorageSync('user_session')?.id;if(!userId)return;try{const result=await callCloud('order-list',{userId});this.orders=result.data||[]}catch(error){this.orders=uni.getStorageSync('user_orders')||[]}}}</script>
<style lang="scss">@import '../../common/portal.scss';.list{margin-top:24rpx}.order{display:flex;align-items:center;margin-bottom:18rpx}.order-icon{display:flex;align-items:center;justify-content:center;width:92rpx;height:92rpx;margin-right:20rpx;border-radius:20rpx;background:#d6e6e3;color:#006d37;font-size:42rpx}.order-main{display:flex;flex:1;flex-direction:column;gap:8rpx}.name{font-size:28rpx;font-weight:700}.points{color:#006d37;font-size:22rpx}.empty{text-align:center;color:#89958e}</style>
